/**
 * @file src/lib/lazyModalMounts.ts
 * Defer heavy modal Svelte mounts until first open.
 */

import { mount, type Component } from 'svelte';
import { handleChunkLoadFailure } from './chunkLoadRecovery.ts';

type ModalMountFn = () => void;

const mountFns = new Map<string, ModalMountFn>();
const mounted = new Set<string>();
const readyPromises = new Map<string, Promise<void>>();
const readyResolvers = new Map<string, () => void>();
const readyRejectors = new Map<string, (err: unknown) => void>();

function ensureReadyPromise(modalId: string): Promise<void> {
  let promise = readyPromises.get(modalId);
  if (!promise) {
    promise = new Promise<void>((resolve, reject) => {
      readyResolvers.set(modalId, resolve);
      readyRejectors.set(modalId, reject);
    });
    readyPromises.set(modalId, promise);
  }
  return promise;
}

function markModalReady(modalId: string): void {
  readyResolvers.get(modalId)?.();
  readyResolvers.delete(modalId);
  readyRejectors.delete(modalId);
}

function markModalFailed(modalId: string, err: unknown): void {
  readyRejectors.get(modalId)?.(err);
  readyResolvers.delete(modalId);
  readyRejectors.delete(modalId);
}

function waitForElement(id: string, timeoutMs: number): Promise<void> {
  return new Promise((resolve) => {
    const start = Date.now();
    const tick = () => {
      if (document.getElementById(id)) {
        resolve();
        return;
      }
      if (Date.now() - start >= timeoutMs) {
        resolve();
        return;
      }
      requestAnimationFrame(tick);
    };
    tick();
  });
}

export function registerLazyModalMount(modalId: string, fn: ModalMountFn): void {
  mountFns.set(modalId, fn);
}

export function isLazyModalMounted(modalId: string): boolean {
  return mounted.has(modalId);
}

export function ensureLazyModalMounted(modalId: string): void {
  if (mounted.has(modalId)) return;
  const fn = mountFns.get(modalId);
  if (!fn) return;
  mounted.add(modalId);
  fn();
}

export async function ensureLazyModalReady(modalId: string): Promise<void> {
  if (mounted.has(modalId)) {
    if (modalId === 'offlineModal') {
      await waitForElement('offlineModalBody', 5000);
    }
    return;
  }
  const promise = ensureReadyPromise(modalId);
  ensureLazyModalMounted(modalId);
  try {
    await promise;
  } catch {
    return;
  }
  if (modalId === 'offlineModal') {
    await waitForElement('offlineModalBody', 5000);
  }
}

function mountModalIntoTarget(targetId: string, ComponentType: Component): void {
  const target = document.getElementById(targetId);
  if (!target || target.getAttribute('data-svelte-ui') === '1') return;
  target.innerHTML = '';
  target.setAttribute('data-svelte-ui', '1');
  mount(ComponentType, { target });
}

export function mountLazyModalComponent(
  modalId: string,
  targetId: string,
  ComponentType: Component,
): void {
  ensureReadyPromise(modalId);
  registerLazyModalMount(modalId, () => {
    mountModalIntoTarget(targetId, ComponentType);
    markModalReady(modalId);
  });
}

export function mountLazyModalComponentAsync(
  modalId: string,
  targetId: string,
  loader: () => Promise<{ default: Component }>,
): void {
  ensureReadyPromise(modalId);
  registerLazyModalMount(modalId, () => {
    void loader()
      .then(({ default: ComponentType }) => {
        mountModalIntoTarget(targetId, ComponentType);
        markModalReady(modalId);
      })
      .catch((err: unknown) => {
        mounted.delete(modalId);
        markModalFailed(modalId, err);
        handleChunkLoadFailure(`modal:${modalId}`, err);
      });
  });
}

/** Modal ids registered for lazy mount (audit + OPEN_MODAL). */
export const LAZY_MODAL_IDS = new Set([
  'statsModal',
  'creatureModal',
  'relicModal',
  'farmingMetricsModal',
  'martAutoPurchaseModal',
  'dailyLoginModal',
  'masteryModal',
  'zoneMapModal',
  'miltankFarmModal',
  'berryTreeModal',
  'pokePelagoModal',
  'ultimateSlotModal',
  'logModal',
  'synergyListModal',
  'captureModal',
  'eggHatchModal',
  'evolutionModal',
  'zoneTierModal',
  'offlineModal',
  'profChenWikiModal',
]);

/** Await lazy modal Svelte mount before reading DOM or adding `.show`. */
export async function awaitLazyModalReady(modalId: string): Promise<void> {
  if (LAZY_MODAL_IDS.has(modalId)) {
    await ensureLazyModalReady(modalId);
    return;
  }
  ensureLazyModalMounted(modalId);
}

export async function ensureLazyModalBeforeShowAsync(modalId: string): Promise<void> {
  if (LAZY_MODAL_IDS.has(modalId)) {
    await awaitLazyModalReady(modalId);
  }
}

/** @deprecated Use ensureLazyModalBeforeShowAsync — sync mount kick-off races async import. */
export function ensureLazyModalBeforeShow(modalId: string): void {
  if (LAZY_MODAL_IDS.has(modalId)) ensureLazyModalMounted(modalId);
}
