/**
 * @file serviceWorkerUpdates.ts
 * Service Worker registration and in-game update banner (wait-for-user activation).
 */

import { uiText } from '../ui/i18n.ts';
import type { GameRuntime } from '../types/game.js';

const UPDATE_CHECK_INTERVAL_MS = 30 * 60 * 1000;
const APPLY_UPDATE_RELOAD_TIMEOUT_MS = 8000;
const SW_URL = './sw.js';
const MANIFEST_URL = './asset-manifest.json';
const DISMISS_KEY = 'poketime:dismissedSwUpdate';
const DISMISS_VERSION_KEY = 'poketime:dismissedSwVersion';
const DEBUG_WORKER_ID = 'debug://update-banner-simulated';

let registration: ServiceWorkerRegistration | null = null;
let registrationResolved = false;
let pendingUpdateWorker: ServiceWorker | null = null;
let pendingDeployVersion: string | null = null;
/** Set when the player explicitly applies an update; only then reload on controllerchange. */
let reloadOnControllerChange = false;
let bannerDismissedThisSession = false;
let bannerUiReady = false;
let swInitDone = false;
let forceSwEnabledForTests = false;
let debugSimulateUpdate = false;
let controllerChangeListenerBound = false;
let onBannerDocumentClick: ((e: Event) => void) | null = null;

function isSwSupported(): boolean {
    if (!forceSwEnabledForTests && import.meta.env.DEV) return false;
    if (typeof window === 'undefined') return false;
    const proto = window.location.protocol;
    if (proto !== 'http:' && proto !== 'https:') return false;
    return 'serviceWorker' in navigator;
}

function getBannerEls() {
    return {
        root: document.getElementById('updateBanner'),
        text: document.getElementById('updateBannerText'),
        action: document.getElementById('updateBannerAction') as HTMLButtonElement | null,
        close: document.getElementById('updateBannerClose') as HTMLButtonElement | null,
    };
}

function getGameRef(): GameRuntime | null {
    return (typeof globalThis.game !== 'undefined' && globalThis.game) ? globalThis.game : null;
}

function getWaitingWorkerId(worker: ServiceWorker): string {
    return worker.scriptURL || DEBUG_WORKER_ID;
}

function readDismissedWorkerId(): string | null {
    try {
        return sessionStorage.getItem(DISMISS_KEY);
    } catch {
        return null;
    }
}

function readDismissedVersion(): string | null {
    try {
        return localStorage.getItem(DISMISS_VERSION_KEY);
    } catch {
        return null;
    }
}

function isDismissedForWorker(worker: ServiceWorker): boolean {
    const dismissed = readDismissedWorkerId();
    return dismissed != null && dismissed === getWaitingWorkerId(worker);
}

function isDismissedForDeployVersion(version: string | null): boolean {
    if (!version) return false;
    return readDismissedVersion() === version;
}

function persistDismissForWorker(worker: ServiceWorker): void {
    try {
        sessionStorage.setItem(DISMISS_KEY, getWaitingWorkerId(worker));
    } catch {
        /* noop */
    }
}

function persistDismissForVersion(version: string): void {
    try {
        localStorage.setItem(DISMISS_VERSION_KEY, version);
    } catch {
        /* noop */
    }
}

function clearDismissedWorkerStorage(): void {
    try {
        sessionStorage.removeItem(DISMISS_KEY);
        localStorage.removeItem(DISMISS_VERSION_KEY);
    } catch {
        /* noop */
    }
}

async function fetchManifestVersion(): Promise<string | null> {
    try {
        const res = await fetch(MANIFEST_URL, { cache: 'no-store' });
        if (!res.ok) return null;
        const manifest = await res.json() as { version?: unknown };
        return typeof manifest.version === 'string' && manifest.version ? manifest.version : null;
    } catch {
        return null;
    }
}

async function refreshPendingDeployVersion(): Promise<void> {
    if (!registration?.waiting && !pendingUpdateWorker) {
        pendingDeployVersion = null;
        return;
    }
    const version = await fetchManifestVersion();
    if (version) pendingDeployVersion = version;
}

function resolveWaitingWorker(worker?: ServiceWorker | null): ServiceWorker | null {
    if (worker) return worker;
    if (pendingUpdateWorker) return pendingUpdateWorker;
    return registration?.waiting ?? null;
}

function isUpdatePending(worker?: ServiceWorker | null): boolean {
    if (import.meta.env.DEV && debugSimulateUpdate) return true;
    const w = resolveWaitingWorker(worker);
    if (!w) return false;
    if (typeof navigator === 'undefined' || !('serviceWorker' in navigator)) return false;
    return !!navigator.serviceWorker.controller;
}

function shouldShowUpdateBanner(worker?: ServiceWorker | null): boolean {
    if (bannerDismissedThisSession) return false;
    if (!isUpdatePending(worker)) return false;
    if (import.meta.env.DEV && debugSimulateUpdate) return true;
    if (pendingDeployVersion && isDismissedForDeployVersion(pendingDeployVersion)) return false;
    const w = resolveWaitingWorker(worker);
    if (!w) return false;
    return !isDismissedForWorker(w);
}

function clearDismissedWorkerIfGone(): void {
    if (!registrationResolved) return;
    if (import.meta.env.DEV && debugSimulateUpdate) return;
    if (!registration?.waiting && !pendingUpdateWorker) {
        clearDismissedWorkerStorage();
        pendingDeployVersion = null;
    }
}

function reloadForAppliedUpdate(): void {
    reloadOnControllerChange = false;
    clearDismissedWorkerStorage();
    pendingUpdateWorker = null;
    pendingDeployVersion = null;
    window.location.reload();
}

export function refreshUpdateBannerLabels(applying = false): void {
    const { root, text, action, close } = getBannerEls();
    if (!root || !text || !action || !close) return;
    const game = getGameRef();
    text.textContent = uiText('banner.update.title', 'Une nouvelle version est disponible !', {}, game);
    if (applying) {
        action.textContent = uiText('banner.update.applying', 'Mise à jour…', {}, game);
        action.disabled = true;
    } else {
        action.textContent = uiText('banner.update.action', 'Mettre à jour', {}, game);
        action.disabled = false;
    }
    close.setAttribute('aria-label', uiText('banner.update.close', 'Fermer', {}, game));
}

function setApplyingState(): void {
    refreshUpdateBannerLabels(true);
}

function bindBannerClickDelegation(): void {
    if (onBannerDocumentClick) return;
    onBannerDocumentClick = (e: Event) => {
        const target = e.target;
        if (!(target instanceof Element)) return;

        if (target.closest('#updateBannerAction')) {
            e.preventDefault();
            void applyUpdateNow();
            return;
        }
        if (target.closest('#updateBannerClose')) {
            void dismissUpdateBanner();
            return;
        }
        if (target.closest('[data-lang]')) {
            setTimeout(() => refreshUpdateBannerLabels(), 0);
        }
    };
    document.addEventListener('click', onBannerDocumentClick);
}

function ensureControllerChangeListener(): void {
    if (controllerChangeListenerBound || typeof navigator === 'undefined' || !('serviceWorker' in navigator)) {
        return;
    }
    controllerChangeListenerBound = true;
    navigator.serviceWorker.addEventListener('controllerchange', () => {
        if (!reloadOnControllerChange) return;
        reloadForAppliedUpdate();
    });
}

function maybeShowDebugBanner(): void {
    if (!import.meta.env.DEV || typeof window === 'undefined') return;
    try {
        const params = new URLSearchParams(window.location.search);
        if (params.get('debugUpdateBanner') !== '1') return;
        debugSimulateUpdate = true;
        pendingUpdateWorker = {
            scriptURL: DEBUG_WORKER_ID,
            postMessage: () => {},
        } as unknown as ServiceWorker;
        notifyUpdateAvailable(pendingUpdateWorker);
    } catch {
        /* noop */
    }
}

export function hideUpdateBanner(): void {
    const { root } = getBannerEls();
    if (root) root.hidden = true;
    document.body.classList.remove('update-banner-visible');
}

export function notifyUpdateAvailable(worker?: ServiceWorker): void {
    if (!shouldShowUpdateBanner(worker)) {
        hideUpdateBanner();
        return;
    }
    const w = resolveWaitingWorker(worker);
    if (w) pendingUpdateWorker = w;
    ensureUpdateBannerUi();
    refreshUpdateBannerLabels();
    const { root } = getBannerEls();
    if (!root) return;
    root.hidden = false;
    document.body.classList.add('update-banner-visible');
}

export async function syncBannerStateAsync(): Promise<void> {
    if (registrationResolved) {
        clearDismissedWorkerIfGone();
        await refreshPendingDeployVersion();
    }
    const waiting = resolveWaitingWorker();
    if (shouldShowUpdateBanner(waiting ?? undefined)) {
        notifyUpdateAvailable(waiting ?? undefined);
    } else {
        hideUpdateBanner();
    }
}

export function syncBannerState(): void {
    void syncBannerStateAsync();
}

export function ensureUpdateBannerUi(): void {
    if (bannerUiReady) {
        refreshUpdateBannerLabels();
        return;
    }
    bannerUiReady = true;
    bindBannerClickDelegation();
    refreshUpdateBannerLabels();
    hideUpdateBanner();
    maybeShowDebugBanner();
}

export function isUpdateBannerVisible(): boolean {
    const root = document.getElementById('updateBanner');
    return root != null && !root.hidden;
}

/** @deprecated Prefer notifyUpdateAvailable — kept for tests and legacy callers. */
export function showUpdateBanner(): void {
    notifyUpdateAvailable();
}

export async function dismissUpdateBanner(): Promise<void> {
    bannerDismissedThisSession = true;
    const w = resolveWaitingWorker();
    if (w) persistDismissForWorker(w);
    const version = pendingDeployVersion ?? await fetchManifestVersion();
    if (version) {
        pendingDeployVersion = version;
        persistDismissForVersion(version);
    }
    hideUpdateBanner();
}

export async function applyUpdateNow(): Promise<void> {
    if (!isUpdatePending()) return;

    const game = getGameRef();
    if (game && typeof game.saveGame === 'function') {
        game.saveGame();
    }

    if (import.meta.env.DEV && debugSimulateUpdate) {
        hideUpdateBanner();
        debugSimulateUpdate = false;
        pendingUpdateWorker = null;
        return;
    }

    const reg = registration
        ?? await navigator.serviceWorker.getRegistration(SW_URL).catch(() => null);
    if (reg && !registration) registration = reg;
    if (!reg) return;

    let waiting = pendingUpdateWorker ?? reg.waiting ?? null;
    if (!waiting) {
        await reg.update().catch(() => {});
        waiting = pendingUpdateWorker ?? reg.waiting ?? null;
    }
    if (!waiting) return;

    ensureControllerChangeListener();
    reloadOnControllerChange = true;
    setApplyingState();

    let reloaded = false;
    const tryReload = () => {
        if (reloaded) return;
        reloaded = true;
        reloadForAppliedUpdate();
    };

    waiting.addEventListener('statechange', () => {
        if (waiting.state === 'activated') {
            tryReload();
        }
    });

    window.setTimeout(() => {
        tryReload();
    }, APPLY_UPDATE_RELOAD_TIMEOUT_MS);

    waiting.postMessage({ type: 'SKIP_WAITING' });
}

function onWorkerInstalled(worker: ServiceWorker, hasController: boolean): void {
    if (worker.state !== 'installed') return;
    if (!hasController) {
        worker.postMessage({ type: 'SKIP_WAITING' });
        return;
    }
    pendingUpdateWorker = worker;
    syncBannerState();
}

function initServiceWorkerRegistration(): void {
    if (swInitDone || !isSwSupported()) return;
    swInitDone = true;

    ensureControllerChangeListener();

    navigator.serviceWorker.register(SW_URL)
        .then((reg) => {
            registration = reg;
            registrationResolved = true;

            if (reg.waiting && !navigator.serviceWorker.controller) {
                reg.waiting.postMessage({ type: 'SKIP_WAITING' });
            } else {
                syncBannerState();
            }

            reg.addEventListener('updatefound', () => {
                const worker = reg.installing;
                if (!worker) return;
                worker.addEventListener('statechange', () => {
                    if (worker.state === 'installed') {
                        onWorkerInstalled(worker, !!navigator.serviceWorker.controller);
                    }
                });
            });

            setInterval(() => {
                reg.update().catch(() => {}).finally(() => syncBannerState());
            }, UPDATE_CHECK_INTERVAL_MS);

            document.addEventListener('visibilitychange', () => {
                if (document.visibilityState === 'visible') {
                    reg.update().catch(() => {}).finally(() => syncBannerState());
                }
            });
        })
        .catch(() => {});
}

export function initServiceWorkerUpdates(): void {
    ensureUpdateBannerUi();
    initServiceWorkerRegistration();
}

/** @internal Reset module state between unit tests. */
export function _resetServiceWorkerUpdatesForTests(options?: { keepDismiss?: boolean }): void {
    if (onBannerDocumentClick) {
        document.removeEventListener('click', onBannerDocumentClick);
        onBannerDocumentClick = null;
    }
    registration = null;
    registrationResolved = false;
    pendingUpdateWorker = null;
    pendingDeployVersion = null;
    reloadOnControllerChange = false;
    bannerDismissedThisSession = false;
    bannerUiReady = false;
    swInitDone = false;
    forceSwEnabledForTests = false;
    debugSimulateUpdate = false;
    controllerChangeListenerBound = false;
    if (!options?.keepDismiss) {
        clearDismissedWorkerStorage();
    }
}

/** @internal Allow SW logic to run under Vitest (import.meta.env.DEV is true). */
export function _enableServiceWorkerForTests(): void {
    forceSwEnabledForTests = true;
}

/** @internal */
export function _setRegistrationForTests(reg: ServiceWorkerRegistration | null): void {
    registration = reg;
}

/** @internal */
export function _setRegistrationResolvedForTests(resolved: boolean): void {
    registrationResolved = resolved;
}

/** @internal */
export function _setPendingDeployVersionForTests(version: string | null): void {
    pendingDeployVersion = version;
}

/** @internal */
export function _setPendingUpdateWorkerForTests(worker: ServiceWorker | null): void {
    pendingUpdateWorker = worker;
}

/** @internal */
export function syncBannerStateForTests(): void {
    syncBannerState();
}

/** @internal */
export async function syncBannerStateAsyncForTests(): Promise<void> {
    await syncBannerStateAsync();
}

/** @internal Exercise install vs update branching without a live SW. */
export function _onWorkerInstalledForTests(worker: ServiceWorker, hasController: boolean): void {
    onWorkerInstalled(worker, hasController);
}
