/**
 * Recover from Vite dynamic import failures (stale chunk 404 after deploy).
 */

import { notifyUpdateAvailable } from './serviceWorkerUpdates.ts';

const CHUNK_RECOVERY_SHOWN_KEY = 'poketime:chunkRecoveryShown';

const CHUNK_LOAD_PATTERNS = [
  /failed to fetch dynamically imported module/i,
  /importing a module script failed/i,
  /error loading dynamically imported module/i,
];

export function isViteChunkLoadError(err: unknown): boolean {
  const message = err instanceof Error ? err.message : String(err ?? '');
  return CHUNK_LOAD_PATTERNS.some((re) => re.test(message));
}

function showChunkRecoveryToast(context: string): void {
  try {
    if (sessionStorage.getItem(CHUNK_RECOVERY_SHOWN_KEY) === '1') return;
    sessionStorage.setItem(CHUNK_RECOVERY_SHOWN_KEY, '1');
  } catch {
    /* private mode */
  }

  notifyUpdateAvailable();

  void import('../../toastManager.ts').then(({ toast }) => {
    const title = 'Mise à jour disponible';
    const body = context.includes('tab:')
      ? 'Rechargez la page pour afficher cet onglet (nouvelle version déployée).'
      : 'Rechargez la page pour continuer (nouvelle version déployée).';
    if (toast.info) {
      toast.info(title, `${body} (F5 pour recharger)`, { duration: 12000 });
    }
  }).catch(() => {
    /* toast optional */
  });
}

/** Log + prompt reload when a lazy chunk fails to load (e.g. post-deploy 404). */
export function handleChunkLoadFailure(context: string, err: unknown): void {
  if (!isViteChunkLoadError(err)) {
    console.error(`[chunkLoad] ${context}`, err);
    return;
  }
  console.warn(`[chunkLoad] stale chunk (${context}) — reload required`, err);
  showChunkRecoveryToast(context);
}

/** @internal Vitest only */
export function resetChunkLoadRecoveryForTests(): void {
  try {
    sessionStorage.removeItem(CHUNK_RECOVERY_SHOWN_KEY);
  } catch {
    /* noop */
  }
}
